            *rms_rad = 0.0;
            return ADCS_E_RANGE;
        }
        if (adcs_vec3_normalize(&predicted_body_vectors[k], ADCS_EPS_NORM, &p_unit) != ADCS_OK) {
            *rms_rad = 0.0;
            return ADCS_E_RANGE;
        }

        dot = adcs_vec3_dot(&b_unit, &p_unit);
        dot = ADCS_CLAMP(dot, -1.0, 1.0);
